from collections import defaultdict

class Solution:
    def groupThePeople(self, groupSizes: list[int]) -> list[list[int]]:
        buckets = defaultdict(list)
        res = []
        for i, sz in enumerate(groupSizes):
            buckets[sz].append(i)
            if len(buckets[sz]) == sz:
                res.append(buckets.pop(sz))
        return res

class Solution {
public:
    std::vector<std::vector<int>> groupThePeople(std::vector<int>& groupSizes) {
        std::unordered_map<int, std::vector<int>> buckets;
        std::vector<std::vector<int>> res;
        for (int i = 0; i < groupSizes.size(); ++i) {
            int sz = groupSizes[i];
            buckets[sz].push_back(i);
            if (buckets[sz].size() == sz) {
                res.push_back(std::move(buckets[sz]));
                buckets.erase(sz);
            }
        }
        return res;
    }
};

class Solution {
    public java.util.List<java.util.List<Integer>> groupThePeople(int[] groupSizes) {
        java.util.Map<Integer, java.util.List<Integer>> buckets = new java.util.HashMap<>();
        java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();
        for (int i = 0; i < groupSizes.length; i++) {
            int sz = groupSizes[i];
            buckets.computeIfAbsent(sz, k -> new java.util.ArrayList<>()).add(i);
            if (buckets.get(sz).size() == sz) {
                res.add(buckets.remove(sz));
            }
        }
        return res;
    }
}

var groupThePeople = function(groupSizes) {
    const buckets = new Map();
    const res = [];
    for (let i = 0; i < groupSizes.length; i++) {
        const sz = groupSizes[i];
        if (!buckets.has(sz)) buckets.set(sz, []);
        const b = buckets.get(sz);
        b.push(i);
        if (b.length === sz) {
            res.push(b);
            buckets.delete(sz);
        }
    }
    return res;
};
